document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>panel(b.dataset.panel));$('adminSearch').oninput=()=>{if(current)drawAdmin()};$('addProduct').onclick=()=>{if(!current)return;if(!current.categories.length){$('addCategory').click();return}let c=current.categories.length===1?current.categories[0]:current.categories[Number(prompt('رقم القسم: '+current.categories.map((c,i)=>(i+1)+' '+tr(c.name,'ar')).join(' / ')))-1];if(c){panel('items');addProduct(c)}};
