function move(arr,i,delta,isCategory){let j=i+delta;if(j<0||j>=arr.length)return;[arr[i],arr[j]]=[arr[j],arr[i]];if(isCategory)selectedCategory=j;openItem=-1;render()}
async function list(){let snap=await getDocs(query(collection(db,'menus'),where('owner','==',user.uid)));$('restaurants').replaceChildren();let o=el('option','اختر مطعم');o.value='';$('restaurants').append(o);snap.forEach(d=>{let o=el('option',tr(d.data().name,'ar')||d.id);o.value=d.id;$('restaurants').append(o)});if(id)$('restaurants').value=id}
async function load(key){id=key;let d=await getDoc(doc(db,'menus',id));if(!d.exists())return;current=d.data();selectedCategory=0;openItem=-1;savedRefs=refs(current);await hydrate(current,id);let v=await getDoc(doc(db,'visits',id));$('stats').textContent='الزيارات المسجلة: '+(v.data()?.count||0);render()}
async function save(){if(!current)throw Error('أنشئ مطعم أولاً');if(!tr(current.name,'ar')||!current.expires)throw Error('أدخل الاسم وتاريخ انتهاء الاشتراك');current.owner=user.uid;current.expiryAt=Timestamp.fromDate(new Date(current.expires+'T23:59:59+03:00'));const next=refs(current), batch=writeBatch(db);const added=next.filter(k=>!savedRefs.includes(k)), removed=savedRefs.filter(k=>!next.includes(k));if(added.length+removed.length>498)throw Error('احفظ الصور على دفعات أصغر');for(const k of added){if(!images.has(k))throw Error('الصورة غير متاحة');batch.set(doc(db,'menus',id,'images',k),{data:images.get(k)});}for(const k of removed)batch.delete(doc(db,'menus',id,'images',k));batch.set(doc(db,'menus',id),current);await batch.commit();savedRefs=next;let v=await getDoc(doc(db,'visits',id));if(!v.exists())await setDoc(doc(db,'visits',id),{count:0});await list();await refreshOverview();status('تم الحفظ والنشر')}
async function start(){if(firebaseConfig.apiKey==='REPLACE_ME'){status('اربط Firebase أولاً — راجع README');return}let app=initializeApp(firebaseConfig);db=getFirestore(app);auth=getAuth(app);let key=new URLSearchParams(location.search).get('menu');if(key){document.body.classList.add('public-mode');try{let d=await getDoc(doc(db,'menus',key));if(!d.exists()||expired(d.data()))throw Error();await hydrate(d.data(),key);menu(d.data(),$('public'),true);try{if(!sessionStorage.getItem('visit:'+key)){await updateDoc(doc(db,'visits',key),{count:increment(1)});sessionStorage.setItem('visit:'+key,'1')}}catch(e){console.warn(e)}}catch{$('public').textContent='المنيو غير متاح حالياً / Menu unavailable / مێنیو بەردەست نییە'}return}onAuthStateChanged(auth,guard(async u=>{user=u;$('login').hidden=!!u;$('admin').hidden=!u;$('logout').hidden=!u;if(u){await list();if($('restaurants').options.length>1){$('restaurants').selectedIndex=1;await load($('restaurants').value)}else{ id=crypto.randomUUID();current=fresh();savedRefs=[];render()}await refreshOverview();panel('dashboard')}else{current=null;id=null}}));}
