$('loginForm').onsubmit=async e=>{e.preventDefault();const b=$('signin'),err=$('loginError');err.hidden=true;b.disabled=true;b.textContent='جاري تسجيل الدخول…';try{await signInWithEmailAndPassword(auth,$('email').value.trim(),$('password').value);$('password').value='';}catch(e){const messages={'auth/invalid-credential':'البريد الإلكتروني أو كلمة المرور غير صحيحة.','auth/wrong-password':'البريد الإلكتروني أو كلمة المرور غير صحيحة.','auth/user-not-found':'البريد الإلكتروني أو كلمة المرور غير صحيحة.','auth/invalid-email':'تحقق من البريد الإلكتروني.','auth/too-many-requests':'محاولات كثيرة. حاول لاحقاً.','auth/network-request-failed':'تحقق من اتصال الإنترنت.'};err.textContent=messages[e.code]||'تعذر تسجيل الدخول. تحقق من الإعدادات وحاول مجدداً.';err.hidden=false;}finally{b.disabled=false;b.textContent='تسجيل الدخول ←'}};$('logout').onclick=guard(()=>signOut(auth));$('new').onclick=guard(()=>{if(current&&!confirm('إنشاء مطعم جديد؟ التعديلات غير المحفوظة ستضيع'))return;id=crypto.randomUUID();current=fresh();savedRefs=[];$('stats').textContent='الزيارات: 0';render();panel('settings')});$('restaurants').onchange=guard(async()=>{if($('restaurants').value){if(!confirm('تأكد من حفظ التعديلات قبل تبديل المطعم')){$('restaurants').value=id;return}await load($('restaurants').value);panel('items')}});$('save').onclick=guard(save);$('delete').onclick=guard(async()=>{if(current&&confirm('حذف المطعم نهائياً؟')){const batch=writeBatch(db);if(savedRefs.length>497)throw Error('احذف بعض الصور واحفظ أولاً');for(const k of savedRefs)batch.delete(doc(db,'menus',id,'images',k));batch.delete(doc(db,'visits',id));batch.delete(doc(db,'menus',id));batch.delete(doc(db,'billing',id));await batch.commit();id=crypto.randomUUID();current=fresh();savedRefs=[];render();await list();await refreshOverview()}});$('addCategory').onclick=()=>{if(current){current.categories.push({name:blank(),items:[]});selectedCategory=current.categories.length-1;openItem=-1;editing=current.categories[selectedCategory];panel('items');render()}};$('uploadLogo').onclick=guard(async()=>{current.logo=await upload($('logo').files[0]);renderPreview();status('تم تجهيز الشعار؛ احفظ للنشر')});$('uploadCover').onclick=guard(async()=>{current.cover=await upload($('cover').files[0]);renderPreview();status('احفظ للنشر')});$('removeCover').onclick=()=>{if(current){current.cover='';renderPreview()}};$('removeLogo').onclick=()=>{if(current){current.logo='';renderPreview();status('احفظ للنشر')}};$('copy').onclick=guard(()=>navigator.clipboard.writeText(url()));$('qr').onclick=guard(()=>{$('qrcode').replaceChildren();new QRCode($('qrcode'),{text:url(),width:220,height:220})});start().catch(e=>status(e.message));
